// Cache-aside invalidation: DB is source of truth
async function updateCacheAside(id, review) {
  await db.tx(async () => {
    await db.insertReview(id, review);
    await db.updateRatingAggregate(id);
  });
  await cache.del(`business:${id}:rating`); // next read rebuilds cache
}

// Write-through: ack only after DB and cache are updated
async function updateWriteThrough(id, review) {
  const avg = await db.tx(async () => {
    await db.insertReview(id, review);
    return db.updateRatingAggregate(id);
  });
  await cache.set(`business:${id}:rating`, avg);
  return avg; // durable before returning
}

// Write-behind: ack before DB commit; worker flushes later
async function updateWriteBehind(id, review) {
  await cache.applyReview(id, review);
  await queue.enqueue({ id, review }); // must be durable
  return 'accepted';
}

async function flushWorker(event) {
  try {
    await db.applyReview(event.id, event.review);
    await queue.ack(event);
  } catch (err) {
    await queue.retry(event); // without retry/WAL, data can be lost
  }
}
